import{_ as i,o as e,c as t,a3 as n}from"./chunks/framework.BvvarXmc.js";const d=JSON.parse('{"title":"Unggah Materi & Tugas Siswa (LMS)","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-guru/lms-materi.md","filePath":"panduan-guru/lms-materi.md","lastUpdated":null}'),s={name:"panduan-guru/lms-materi.md"};function r(l,a,u,m,o,g){return e(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="unggah-materi-tugas-siswa-lms" tabindex="-1">Unggah Materi &amp; Tugas Siswa (LMS) <a class="header-anchor" href="#unggah-materi-tugas-siswa-lms" aria-label="Permalink to &quot;Unggah Materi &amp; Tugas Siswa (LMS)&quot;">​</a></h1><p>Guru dapat membagikan bahan pembelajaran digital dan memberikan tugas mandiri maupun kelompok kepada siswa di luar jam tatap muka kelas.</p><hr><h2 id="_1-membagikan-materi-belajar" tabindex="-1">1. Membagikan Materi Belajar <a class="header-anchor" href="#_1-membagikan-materi-belajar" aria-label="Permalink to &quot;1. Membagikan Materi Belajar&quot;">​</a></h2><ol><li>Masuk ke menu <strong>LMS &amp; Pembelajaran</strong> <strong>Materi Pelajaran</strong>.</li><li>Klik tombol <strong>+ Tambah Materi Baru</strong>.</li><li>Isi informasi materi: <ul><li><strong>Mata Pelajaran &amp; Kelas Tujuan</strong>.</li><li><strong>Judul Topik Pembahasan</strong> (misal: <em>Bab 3 - Teori Relativitas Khusus</em>).</li><li><strong>Deskripsi Ringkasan</strong>.</li></ul></li><li>Lampiran konten materi dapat berupa: <ul><li><strong>File Dokumen</strong>: PDF modul, presentasi PowerPoint, dokumen Word.</li><li><strong>Tautan Video</strong>: Sematkan link video pembelajaran YouTube atau Google Drive.</li></ul></li><li>Klik <strong>Publikasikan Materi</strong>. Materi akan langsung tampil di beranda portal siswa terkait.</li></ol><hr><h2 id="_2-membuat-menilai-tugas-siswa" tabindex="-1">2. Membuat &amp; Menilai Tugas Siswa <a class="header-anchor" href="#_2-membuat-menilai-tugas-siswa" aria-label="Permalink to &quot;2. Membuat &amp; Menilai Tugas Siswa&quot;">​</a></h2><ol><li>Di menu LMS, buka tab <strong>Tugas (Assignments)</strong> Klik <strong>+ Buat Tugas Baru</strong>.</li><li>Tuliskan instruksi tugas dan tentukan <strong>Batas Waktu Pengumpulan (Deadline)</strong>.</li><li>Setelah siswa mengumpulkan tugas berupa file atau teks: <ul><li>Guru membuka daftar tugas yang telah masuk.</li><li>Guru dapat membaca file kiriman siswa langsung di browser.</li><li>Masukkan <strong>Nilai (Skala 0 - 100)</strong> dan ketikkan <strong>Catatan Evaluasi / Masukan Guru</strong>.</li><li>Klik <strong>Kirim Penilaian</strong>. Nilai akan otomatis terekam ke buku nilai siswa.</li></ul></li></ol>',8)])])}const p=i(s,[["render",r]]);export{d as __pageData,p as default};
